def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
            by_depth = {}
            for y, x in cells:
                d = min(y-r0, r1-y, x-c0, c1-x)
                by_depth.setdefault(d, []).append(grid[y][x])
            ordered = []
            for d in sorted(by_depth):
                color = Counter(by_depth[d]).most_common(1)[0][0]
                if not ordered or color != ordered[-1]:
                    ordered.append(color)
            mapping = dict(zip(ordered, reversed(ordered)))
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
